<?php
declare(strict_types=1);
$base=rtrim((string)getenv('OGPN_API_URL'),'/');$token=(string)getenv('OGPN_API_TOKEN');$id=(string)(getenv('OGPN_WORKER_ID')?:gethostname());if($base===''||$token===''){fwrite(STDERR,"OGPN_API_URL et OGPN_API_TOKEN requis.\n");exit(2);}function callApi(string $method,string $url,string $token,?array $body=null):array{$ch=curl_init($url);$h=['Authorization: Bearer '.$token,'Accept: application/json'];if($body!==null)$h[]='Content-Type: application/json';curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$h,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>60,CURLOPT_POSTFIELDS=>$body===null?null:json_encode($body)]);$raw=curl_exec($ch);$st=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$e=curl_error($ch);curl_close($ch);if($raw===false||$st<200||$st>=300)throw new RuntimeException("API $st $e $raw");$j=json_decode($raw,true);if(!is_array($j))throw new RuntimeException('JSON API invalide');return $j;}
$plan=callApi('GET',$base.'/worker-plan.php',$token);echo "Worker $id : {$plan['action']} ({$plan['reason']})\n";
if($plan['action']==='discovery'){for($i=0;$i<(int)$plan['limits']['max_cc_pages'];$i++){ $c=callApi('POST',$base.'/common-crawl-claim.php',$token,[]);$j=$c['job']??null;if(!$j){echo "Aucune page Common Crawl en attente.\n";break;} $url='https://index.commoncrawl.org/'.rawurlencode($j['crawl_id']).'-index?url='.rawurlencode('*.'.$j['tld']).'&matchType=domain&output=json&fl=url&page='.(int)$j['page_number'];$raw=file_get_contents($url);if($raw===false)throw new RuntimeException('Common Crawl inaccessible');$urls=[];$rows=0;foreach(preg_split('/\R/',trim($raw))?:[] as $line){if($line==='')continue;$rows++;$x=json_decode($line,true);if(is_array($x)&&is_string($x['url']??null))$urls[]=$x['url'];} $r=callApi('POST',$base.'/common-crawl-ingest.php',$token,['job_id'=>$j['id'],'urls'=>$urls,'rows_received'=>$rows]);echo "CC {$j['tld']} page {$j['page_number']}: {$r['domains_added']} nouveaux domaines.\n";}}
elseif($plan['action']==='scan'){ $max=(int)$plan['limits']['max_scan_domains'];$chunk=(int)$plan['limits']['scan_chunk_size'];$done=0;while($done<$max){$q=callApi('POST',$base.'/scan-claim.php',$token,['limit'=>min($chunk,$max-$done)]);$domains=$q['domains']??[];if(!$domains){echo "Aucun domaine dû.\n";break;}$results=[];foreach($domains as $domain){$url='https://'.$domain;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_USERAGENT=>'OGPN-BOT/2.0 (+https://ogpn.eu)',CURLOPT_RANGE=>'0-1048575']);$html=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$final=(string)curl_getinfo($ch,CURLINFO_EFFECTIVE_URL);curl_close($ch);$lang=null;if(is_string($html)&&preg_match('/<html[^>]+lang=["\']?([a-zA-Z-]+)/i',$html,$m))$lang=strtolower(substr($m[1],0,12));$results[]=['domain'=>$domain,'http_status'=>$status,'final_url'=>$final,'default_language'=>$lang,'selected_language'=>$lang?:'fr','language_source'=>$lang?'html_lang':'default','language_confidence'=>$lang?0.9:0.2,'analysis'=>['alpha'=>true]];}callApi('POST',$base.'/scan-ingest.php',$token,['results'=>$results]);$done+=count($results);echo count($results)." domaines scannés.\n";}}
